# The level/density knob. ``level`` is the longform aggression level (1..5);
# ``density`` scales how many of that level's candidates survive (0..1), so the
# editor can dial pace *within* a level without jumping to the next one.
#
# These two stay as the INTERNAL knobs (and the back-compat API) but are no longer
# what the editor surfaces. The redesign replaces them with two intuitive knobs —
# GAP-LENGTH and RHYTHM (see below) — that ``plan_microcuts`` prefers when given.
MIN_LEVEL = min(EDIT_LEVELS)
MAX_LEVEL = max(EDIT_LEVELS)
DEFAULT_LEVEL = 3
DEFAULT_DENSITY = 1.0

# ── GAP-LENGTH knob (replaces the abstract level) ─────────────────────────────
# "Cut pauses longer than X seconds." A CONTINUOUS minimum-pause threshold that
# directly sets which gaps are cuttable: a silence/pause shorter than this is
# kept. LOWER = more aggressive (cuts shorter pauses); HIGHER = gentler.
#
# Why a seconds value beats the 1-5 level: the old level mapped to discrete
# pause_thresholds (L2=1.0s, L3=0.5s — a 2x jump, the "cliff" Ashley hit at
# L2→L3). Gap-length is the SAME underlying quantity (the pause threshold) but
# continuous, so the editor slides smoothly from gentle to aggressive with no
# cliff. It feeds BOTH cut sources: the measured-silence floor (the bulk of cuts,
# ``silence_microcuts``) uses it verbatim as ``min_dur``, and the word-gap /
# filler / stutter detector picks the discrete level whose pause_threshold is
# nearest (``_level_for_gap_length``) so its richer filler logic still runs.
GAP_LENGTH_MIN = 0.15
GAP_LENGTH_MAX = 1.5
DEFAULT_GAP_LENGTH = 0.4

# ── RHYTHM knob (replaces the density fraction) ───────────────────────────────
# A 1-5 dial for rapid-succession density. Gap-length QUALIFIES which gaps are
# cuttable; RHYTHM then THINS the qualifying cuts by SPACING. ``S(r)`` is the
# minimum kept-content (seconds of surviving material) required between two
# consecutive APPLIED cuts:
#
#   r = 5 → S = 0.0   no constraint — every qualifying cut fires (back-to-back
#                     0.2s machine-gun cuts included).
#   r = 4 → S = 0.5   bars only the tightest rapid-fire clusters.
#   r = 3 → S = 1.2   the MIDDLE: visibly de-clusters 0.2s rapid-fire while the
#                     big pause cuts (spaced > 1.2s apart) all survive.
#   r = 2 → S = 2.0   spreads cuts further; keeps the impactful pauses only.
#   r = 1 → S = 3.0   gentlest rhythm — cuts must be ~3s of content apart.
#
# When two qualifying cuts are closer than ``S`` (measured as the KEPT gap
# between them — cut[i].start - cut[i-1].end), the LONGER-pause cut wins and the
# other is dropped (a greedy, longest-impact-first sweep — see ``_apply_rhythm``).
# Lower rhythm keeps the longer/more-impactful pauses and skips the closely-
# clustered short ones, exactly the "don't fire 0.2s cuts in a row" ask.
#
# The curve is tuned so the MIDDLE (r=3) is the meaningful de-cluster point:
# 1.2s of kept content is far wider than a 0.2s machine-gun gap (those collapse)
# yet narrower than the spacing between genuine sentence pauses (those survive).
RHYTHM_MIN = 1
RHYTHM_MAX = 5
DEFAULT_RHYTHM = 5
_RHYTHM_SPACING: dict[int, float] = {5: 0.0, 4: 0.5, 3: 1.2, 2: 2.0, 1: 3.0}


def _finite(value: Any, default: float) -> float:
    """``float(value)`` when it is finite, else ``default``.

    NaN / ±Infinity make every ``min``/``max`` clamp below return order-dependent
    garbage (NaN compares False against everything, so ``min(hi, nan)`` yields
    ``hi`` purely from argument order — a raw NaN rhythm silently snapped the micro
    layer to an extreme, and a non-finite nudge pushed an edge to NaN/±inf and
    emitted it as a cut boundary, which then serialized as invalid JSON). Coercing
    a non-finite knob to its neutral default HERE, before any clamp/arithmetic,
    makes the pacing math non-finite-safe BY CONSTRUCTION: the output can never be
    NaN and never branches on argument order. A finite value passes straight
    through, so integer/finite behaviour stays byte-identical.
    """
    try:
        v = float(value)
    except (TypeError, ValueError):
        return default
    return v if math.isfinite(v) else default


def _level_for_gap_length(gap_length: float) -> int:
    """The discrete aggression level whose ``pause_threshold`` is nearest ``gap_length``.

    Gap-length is continuous; ``detect_edit_cuts`` (the word-gap + filler +
    stutter detector) only speaks the 1-5 level vocabulary. So the silence FLOOR
    takes ``gap_length`` verbatim (continuous), and the word-gap path runs at the
    nearest level — close enough that its pauses align with the floor, while its
    filler/stutter richness (which the floor doesn't produce) still fires. Ties
    break toward the MORE aggressive level (smaller threshold) so a value exactly
    between two levels leans to cut, matching "lower gap_length = cut more".
    """
    g = max(GAP_LENGTH_MIN, min(GAP_LENGTH_MAX, float(gap_length)))
    # nearest by |pause_threshold - g|; tie → smaller threshold (more aggressive)
    return min(
        EDIT_LEVELS,
        key=lambda lv: (abs(EDIT_LEVELS[lv].pause_threshold - g),
                        EDIT_LEVELS[lv].pause_threshold),
    )


def _spacing_for_rhythm(rhythm: float) -> float:
    """Minimum kept-content spacing ``S(r)`` between consecutive applied cuts.

    The RHYTHM → spacing curve (see ``_RHYTHM_SPACING``), now CONTINUOUS: the
    slider hands a float, so a fractional rhythm interpolates piecewise-LINEARLY
    between the integer anchors (e.g. r = 3.5 lands strictly between the r=3 and
    r=4 spacings). ``r = 5`` → 0 (no thinning); lower ``r`` → wider required
    spacing, so rapid-fire clusters thin out while the impactful pauses survive.

    Integer rhythms return their EXACT anchor value (the ``frac == 0`` snap, no
    float drift), so an old integer save paces identically. Out-of-range clamps
    to ``[RHYTHM_MIN, RHYTHM_MAX]``.
    """
    # Sanitize FIRST: a non-finite rhythm (NaN/±inf) becomes the neutral default
    # DEFAULT_RHYTHM, so the clamp below can't return order-dependent garbage on a
    # NaN (where every comparison is False). A finite rhythm is unchanged.
    r = max(float(RHYTHM_MIN), min(float(RHYTHM_MAX), _finite(rhythm, DEFAULT_RHYTHM)))
    lo = int(r)  # floor (r >= 1, so truncation IS the floor); the lower anchor
    frac = r - lo
    if frac == 0.0:  # integer rhythm — pin the anchor exactly, no interpolation
        return _RHYTHM_SPACING[lo]
    # piecewise-linear blend toward the next (lo + 1) anchor
    return _RHYTHM_SPACING[lo] + (_RHYTHM_SPACING[lo + 1] - _RHYTHM_SPACING[lo]) * frac


# Migration: an OLD saved edit (or an older client) carries ``level``/``density``
# instead of ``gap_length``/``rhythm``. These map the legacy knobs onto the new
# ones so an existing save still loads at a sensible pace.
#   level → gap_length : the level's OLD silence floor
#                        (``_silence_threshold_for_level``), clamped to the
#                        gap-length range. gap_length sets the silence floor —
#                        the bulk of the cuts — verbatim, so migrating from that
#                        floor (NOT the larger word-gap ``pause_threshold``)
#                        reproduces the level's original cut count. So L3 → 0.30s,
#                        L4 → 0.21s, L1 → 1.2s, L5 → 0.09s clamped to 0.15s.
#   density → rhythm   : density is "keep this fraction"; rhythm is "space cuts
#                        out". 1.0 (keep all) → 5 (no spacing); lower density →
#                        lower rhythm (more thinning). A linear bucket across the
#                        five rhythm steps.


def gap_length_for_level(level: int) -> float:
    """Migrate a legacy ``level`` (1..5) to a ``gap_length`` in seconds.

    Returns the level's OLD measured-silence floor (``_silence_threshold_for_level``),
    clamped into the gap-length range. gap_length feeds the silence floor verbatim,
    and that floor produces the bulk of the cuts — so migrating from the silence
    floor (NOT the word-gap ``pause_threshold``, which is a different, larger value)
    is what reproduces the level's original cut count. Using ``pause_threshold`` here
    raised the floor and silently gentled every migrated save (default L3 went
    30 → 17 cuts).
    """
    lv = max(MIN_LEVEL, min(MAX_LEVEL, int(level)))
    return max(GAP_LENGTH_MIN, min(GAP_LENGTH_MAX, _silence_threshold_for_level(lv)))


def rhythm_for_density(density: float) -> int:
    """Migrate a legacy ``density`` (0..1) to a ``rhythm`` (1..5).

    Density was a keep-fraction (1.0 = keep all); rhythm is a spacing dial
    (5 = no spacing). They share a direction — more density ≈ more cuts ≈ higher
    rhythm — so this buckets the 0..1 fraction linearly onto 1..5: 1.0 → 5,
    ~0.8 → 4, ... 0.0 → 1. Not an exact inverse (density thinned by count,
    rhythm thins by spacing), but a sensible, monotonic restore of intent.
    """
    d = max(0.0, min(1.0, float(density)))
    return max(RHYTHM_MIN, min(RHYTHM_MAX, 1 + round(d * (RHYTHM_MAX - RHYTHM_MIN))))

