# ── Reason strings the inspector renders ──────────────────────────────────────


def clarify_reason(cut: EditCut) -> str:
    """A clean, human ``reason`` for the micro-cut inspector row.

    ``detect_edit_cuts`` already labels each cut, but merged cuts carry stacked
    labels ("pause: 1.1s; filler: um") and the verbs differ ("repeat:" vs the
    word "stutter" Ashley uses). This normalizes to the inspector's vocabulary:

      * a pure pause      -> ``"pause: 2.3s"``
      * a pure filler     -> ``"filler: um"``
      * a stutter/repeat  -> ``"stutter: the the"``
      * a merged span     -> the dominant kind + a "+N more" tail, e.g.
                             ``"pause: 1.1s (+1 more)"``

    The classification is *pause-vs-filler-vs-stutter*, cleaner than the raw
    string so the inspector can colour/group rows. Pure presentation -- it never
    changes the cut's timing.
    """
    parts = [p.strip() for p in cut.reason.split(";") if p.strip()]
    if not parts:
        return f"pause: {cut.duration:.1f}s"

    head = parts[0]
    kind, _, detail = head.partition(":")
    kind = kind.strip().lower()
    detail = detail.strip()

    if kind == "repeat":
        # "repeat: the" -> "stutter: the the" (the stammered pair, as heard).
        label = f"stutter: {detail} {detail}" if detail else "stutter"
    elif kind == "filler":
        label = f"filler: {detail}" if detail else "filler"
    elif kind == "pause":
        # Prefer the measured duration; the raw "2.3s" can drift after merges.
        label = f"pause: {cut.duration:.1f}s"
    else:
        label = head

    extra = len(parts) - 1
    if extra > 0:
        label = f"{label} (+{extra} more)"
    return label


def classify(cut: EditCut) -> str:
    """The micro-cut's dominant kind: ``"pause"`` | ``"filler"`` | ``"stutter"``.

    Reads the leading label of the (possibly merged) reason. Used for grouping,
    density weighting, and tests.
    """
    head = cut.reason.split(";")[0]
    kind = head.split(":")[0].strip().lower()
    if kind == "repeat":
        return "stutter"
    if kind in {"pause", "filler"}:
        return kind
    return "pause"


# ── Kept-material intersection (StoryMap beats) ───────────────────────────────


def kept_ranges_from_beats(
    story_map: dict[str, Any] | None,
    duration: float | None = None,
) -> list[tuple[float, float]]:
    """The time ranges the editor KEEPS, from the StoryMap's non-cut beats.

    A beat is kept unless its ``intent == "cut"`` (the 00-CONTRACT keep rule).
    Adjacent kept beats are merged so a micro-cut spanning a beat seam isn't
    split needlessly.

    Returns ``[(start, end), ...]`` sorted, non-overlapping. With no StoryMap we
    return a single all-content range (``[(0, duration)]`` if ``duration`` is
    known, else an empty list meaning "no constraint" -- callers treat empty as
    unconstrained).
    """
    beats = (story_map or {}).get("beats") if story_map else None
    if not beats:
        if duration is not None and duration > 0:
            return [(0.0, float(duration))]
        return []

    kept = [
        (float(b["start"]), float(b["end"]))
        for b in beats
        if b.get("intent") != "cut"
    ]
    kept.sort(key=lambda r: r[0])

    merged: list[tuple[float, float]] = []
    for s, e in kept:
        if merged and s <= merged[-1][1] + 1e-6:
            merged[-1] = (merged[-1][0], max(merged[-1][1], e))
        else:
            merged.append((s, e))
    return merged


def _clip_to_kept(
    cut: EditCut, kept: list[tuple[float, float]]
) -> EditCut | None:
    """Trim a micro-cut to the kept range it sits in; drop it if it sits in none.

    A micro-cut that straddles a kept/cut seam is trimmed to the kept side so we
    never micro-cut material the model already removed (that span is gone
    anyway, and a cut hanging off the edge of a kept range produces a bad seam).
    Empty ``kept`` means "no constraint" -- the cut passes through unchanged.
    """
    if not kept:
        return cut
    for ks, ke in kept:
        if cut.start < ke and cut.end > ks:  # overlaps this kept range
            ns = max(cut.start, ks)
            ne = min(cut.end, ke)
            if ne - ns <= 0:
                return None
            if ns == cut.start and ne == cut.end:
                return cut
            return EditCut(start=ns, end=ne, reason=cut.reason)
    return None


# ── Land edges on measured silence (S0) ───────────────────────────────────────


def _content_spans(words: list[dict]) -> list[tuple[float, float]]:
    """Spans the consolidation merge must NOT swallow: content words + events.

    A kept scrap between two micro-cuts is "near-empty" (mergeable) only if no
    such span lands in it. CONTENT = every spoken token EXCEPT the non-lexical
    hesitation sounds (``_CORE_FILLERS``: um/uh/er/ah/...). A scrap holding only
    an "ah" is near-empty — that is the "ah ah ah ah ah" over-chop consolidation
    collapses — but a scrap with any real word ("and"/"like" included, since they
    can be load-bearing) is protected. Vocalization events (laughter/gasps) count
    as content too, so a merge never swallows one (the S3 vocalization invariant).
    """
    out: list[tuple[float, float]] = []
    for w in words:
        if "start" not in w or "end" not in w:
            continue
        if w.get("type") == "event":
            out.append((float(w["start"]), float(w["end"])))
            continue
        token = str(w.get("word", "")).strip().lower().strip(".,!?;:\"'")
        if not token or token in _CORE_FILLERS:
            continue
        out.append((float(w["start"]), float(w["end"])))
    out.sort()
    return out


def _overlaps_kept(s: float, e: float, kept: list[tuple[float, float]]) -> bool:
    """True if ``[s, e)`` overlaps any kept range (empty kept = unconstrained)."""
    if not kept:
        return True
    return any(s < ke and e > ks for ks, ke in kept)


def _next_silence_onset(
    t: float, silences: list[Silence], window: float, min_dur: float
) -> float | None:
    """Onset of the next substantial measured silence at/after ``t``.

    The dead-air a cut is really removing starts here; used by the FIX 2 start
    snap to push a cut start forward off the word tail and onto the silence.
    Only silences at least ``min_dur`` long count (a 50ms tail-silence isn't the
    pause), and only those whose onset is within ``window`` ahead of ``t``.
    """
    best: float | None = None
    for sil in silences:
        if sil.duration < min_dur:
            continue
        if t <= sil.start <= t + window:
            if best is None or sil.start < best:
                best = sil.start
    return best


# ── Silence-grid candidates (FIX 1) ───────────────────────────────────────────


def silence_microcuts(
    silences: list[Silence],
    kept: list[tuple[float, float]],
    word_spans: list[tuple[float, float]],
    *,
    min_dur: float = MIN_SILENCE_CUT,
    safety: float = SILENCE_SAFETY,
) -> list[EditCut]:
    """Micro-cuts straight off the MEASURED silence grid (audio_boundaries).

    The companion to ``detect_edit_cuts``' word-gap pauses: that one only sees
    dead-air where the word timestamps report a gap, so it misses silence inside
    butt-joined word pairs (84% of #4). This reads the audio's own silences
    instead -- every measured silence at least ``min_dur`` long, inside kept
    material, becomes a removable span.

    Word-safety is enforced structurally: edges are pulled ``safety`` inward and
    then clamped out of any word they still land in (forced-alignment wobble can
    poke a word edge a few ms into a measured silence). A span that collapses or
    can't be made word-safe is dropped. These cuts are level-independent -- they
    come from the audio, not the aggression knob -- so they're a constant floor
    that ``plan_microcuts`` unions with the word-gap/filler/stutter candidates.
    """
    cuts: list[EditCut] = []
    for sil in silences:
        if sil.duration < min_dur:
            continue
        safe = _clamp_out_of_words(sil.start + safety, sil.end - safety, word_spans, safety)
        if safe is None:
            continue
        s, e = safe
        if not _overlaps_kept(s, e, kept):
            continue
        cuts.append(EditCut(start=s, end=e, reason=f"pause: {sil.duration:.1f}s"))
    return cuts


def _silence_threshold_for_level(level: int) -> float:
    """The measured-silence -> cut threshold for an aggression ``level``.

    Anchored at ``MIN_SILENCE_CUT`` for the default level and scaled by the
    level's word-gap ``pause_threshold``, so the silence floor tracks the SAME
    aggression knob as the word gaps (one concept, not two): "Very Subtle" cuts
    only long dead-air (~1.2s), "Cut for Time" cuts down to ~0.1s. A flat,
    level-independent floor would otherwise swamp levels 1-3 into near-identical
    edits and break the "raising the level removes more" invariant.
    """
    base = EDIT_LEVELS[DEFAULT_LEVEL].pause_threshold
    return MIN_SILENCE_CUT * EDIT_LEVELS[level].pause_threshold / base


def snap_microcut_to_silence(
    cut: EditCut,
    silences: list[Silence],
    word_spans: list[tuple[float, float]],
    window: float = SILENCE_SNAP_WINDOW,
    safety: float = SILENCE_SAFETY,
    start_window: float | None = None,
) -> EditCut | None:
    """Move a micro-cut's edges onto the nearest S0 measured silence.

    Mirrors ``audio_boundaries.snap_cuts_to_silence`` but on a single EditCut and
    with a clip-protection guarantee: an edge only moves if the move keeps it out
    of a spoken word. If snapping would land an edge *inside* a word, that edge
    stays where detect_edit_cuts put it (which is already a word boundary). Either
    way the returned cut never has an edge strictly inside a word.

    FIX 2 (start margin): the START edge is forward-aware. When the start
    already sits inside a measured silence, it lands on that silence's onset (the
    established S0 snap). When it sits in the preceding word's TAIL/breath (no
    enclosing silence), it reaches FORWARD up to ``start_window`` to the next
    dead-air onset, so the tail is kept instead of eaten -- the start runs ~0.5s
    early otherwise (Ashley's trims pushed it +0.49s median). Forward-only: a
    start is never pushed earlier into the tail. ``start_window`` never reaches
    less far than ``window``.

    Returns the snapped cut, or ``None`` if it collapsed to zero width.
    """
    sw = START_SNAP_WINDOW if start_window is None else start_window
    sw = max(sw, window)
    s, e = cut.start, cut.end

    sil_e = nearest_silence(e, silences, window)
    if sil_e is not None:
        cand = sil_e.end - safety
        if cand > s and not _inside_word(cand, word_spans):
            e = cand

    sil_s = nearest_silence(s, silences, window)
    if sil_s is not None and sil_s.contains(s):
        # Already in measured silence: land on its onset (audio is quiet there).
        cand = sil_s.start + safety
        if cand < e and not _inside_word(cand, word_spans):
            s = cand
    else:
        # In the word tail: push forward onto the real dead-air onset, keeping
        # the tail. Never earlier than the current start.
        onset = _next_silence_onset(s, silences, sw, MIN_SILENCE_CUT)
        if onset is not None:
            cand = onset + safety
            if s < cand < e and not _inside_word(cand, word_spans):
                s = cand

    if e - s <= 0:
        return None
    return EditCut(start=s, end=e, reason=cut.reason)


# ── Density knob ──────────────────────────────────────────────────────────────


def _apply_density(
    cuts: list[EditCut], density: float
) -> list[EditCut]:
    """Keep a ``density`` fraction of candidate cuts, smallest-impact first.

    ``density == 1.0`` keeps all (the level's full aggression). Lower values drop
    the shortest cuts first -- they remove the least content, so trimming them
    loosens pace with the smallest visible change. ``density <= 0`` keeps none.
    This lets the editor dial pace *within* a level instead of only between
    levels (5 coarse steps -> a continuous knob).
    """
    if density >= 1.0 or not cuts:
        return cuts
    if density <= 0.0:
        return []
    keep_n = max(1, round(len(cuts) * density))
    if keep_n >= len(cuts):
        return cuts
    # Rank by duration descending; keep the top-N highest-impact cuts.
    ranked = sorted(cuts, key=lambda c: c.duration, reverse=True)[:keep_n]
    ranked.sort(key=lambda c: c.start)
    return ranked


# ── Rhythm knob (spacing thinner) ─────────────────────────────────────────────


def _apply_rhythm(cuts: list[EditCut], spacing: float) -> list[EditCut]:
    """Thin qualifying cuts so consecutive applied cuts are ``spacing`` apart.

    The RHYTHM pass (see ``_RHYTHM_SPACING`` / ``_spacing_for_rhythm``). Gap-length
    already QUALIFIED these cuts (each is a long-enough pause); rhythm now enforces
    a minimum KEPT-content gap between the ones we actually apply, so the editor
    won't fire 0.2s cuts back-to-back at lower rhythm.

    ``spacing <= 0`` (rhythm 5) keeps everything. Otherwise a greedy, longest-
    pause-first sweep: walk cuts by DURATION descending (the most impactful pause
    wins ties for the same neighbourhood) and accept one only when the KEPT gap to
    every already-accepted cut is at least ``spacing``. The kept gap between two
    cuts is ``later.start - earlier.end`` — the surviving content between them —
    so two rapid 0.2s cuts 0.15s apart collapse to the longer one, while two big
    pauses several seconds apart both survive. Output is re-sorted by start.

    Word-safety is untouched: this only ever DROPS whole cuts (never edits an
    edge), so every surviving cut keeps the word-safe edges plan_microcuts gave it.
    """
    if spacing <= 0 or len(cuts) < 2:
        return cuts
    # Most impactful first; on equal duration, earlier start wins for stability.
    order = sorted(cuts, key=lambda c: (-c.duration, c.start))
    accepted: list[EditCut] = []
    for cut in order:
        ok = True
        for a in accepted:
            # kept content between the two cuts (whichever is earlier)
            gap = cut.start - a.end if cut.start >= a.end else a.start - cut.end
            if gap < spacing:
                ok = False
                break
        if ok:
            accepted.append(cut)
    accepted.sort(key=lambda c: c.start)
    return accepted


# ── Scrap consolidation ───────────────────────────────────────────────────────


def _consolidate_microcuts(
    cuts: list[EditCut],
    content_spans: list[tuple[float, float]],
    max_scrap: float = SCRAP_MERGE_MAX,
) -> list[EditCut]:
    """Merge rapid micro-cuts split by tiny near-empty scraps into clean cuts.

    Post-pass over the planned (sorted, non-overlapping) micro-cuts. Two adjacent
    cuts collapse into one — swallowing the KEPT scrap between them — when that
    scrap is shorter than ``max_scrap`` AND holds no content span (a real word or
    a vocalization; see ``_content_spans``). Applied TRANSITIVELY: a run of N
    rapid cuts over filler/silence-only scraps becomes a single continuous cut, so
    an over-chopped span ("ah ah ah ah ah") goes as ONE cut instead of little
    bits.

    Word-safe by construction. The merged cut's edges are the OUTER cuts' edges,
    which were already word-safe; the scrap in the middle is swallowed only when
    it carries no content span — so a merge never lands an edge inside a word and
    never deletes a real word. Cuts with any content word between them are left
    untouched: distinguishing a meaningful pause there from rambling is rhythm
    judgment, deliberately out of scope (the LLM editing brain's job).
    """
    if len(cuts) < 2:
        return cuts

    def scrap_clear(s: float, e: float) -> bool:
        """True if the open scrap ``(s, e)`` holds no content span (mergeable)."""
        for ws, we in content_spans:
            if we > s and ws < e:  # any overlap with the scrap interior
                return False
            if ws >= e:  # spans sorted; nothing later can overlap
                break
        return True

    merged: list[EditCut] = [cuts[0]]
    for cut in cuts[1:]:
        prev = merged[-1]
        scrap = cut.start - prev.end
        if scrap < max_scrap and scrap_clear(prev.end, cut.start):
            merged[-1] = EditCut(
                start=prev.start,
                end=max(prev.end, cut.end),
                reason=f"{prev.reason}; {cut.reason}",
            )
        else:
            merged.append(cut)
    return merged


# ── The pacing producer ───────────────────────────────────────────────────────


def plan_microcuts(
    words: list[dict],
    *,
    level: int = DEFAULT_LEVEL,
    density: float = DEFAULT_DENSITY,
    gap_length: float | None = None,
    rhythm: float | None = None,
    story_map: dict[str, Any] | None = None,
    silences: list[Silence] | None = None,
    duration: float | None = None,
) -> list[dict[str, Any]]:
    """Produce paced micro-cuts in the ``/api/microcuts`` shape ``[{start,end,reason}]``.

    The S3 pipeline, in order:

      1. ``detect_edit_cuts(words, level)`` -- the longform candidates at this
         aggression (pauses + fillers + stutters), with vocalizations already
         protected.
      1b. ``silence_microcuts(silences, ...)`` (FIX 1) -- candidates straight off
         the MEASURED silence grid, catching dead-air the word gaps miss because
         the words are butt-joined. Only when ``silences`` is supplied.
      2. intersect with the StoryMap's KEPT beats -- micro-cuts only inside kept
         material (the within-beat jump-cuts; cut-intent beats are removed whole
         elsewhere).
      3. land edges on S0 measured silences -- so no edge clips a word, and the
         START edge reaches the post-word silence (FIX 2) instead of eating the
         word tail.
      3b. union overlapping candidates so the silence-grid and word-gap cuts
         dedupe into single spans.
      4. apply the RHYTHM knob -- thin the qualifying cuts by spacing (drop the
         closely-clustered short cuts, keep the impactful pauses); the legacy
         DENSITY knob (keep-a-fraction) runs instead when ``rhythm`` is None.
      5. clean ``reason`` strings for the inspector.

    The aggression knobs are the redesigned GAP-LENGTH + RHYTHM pair; the legacy
    ``level``/``density`` remain accepted for back-compat (old saves, older
    callers) but ``gap_length``/``rhythm`` win whenever they are supplied.

    Args:
        words: Hammy word list (ideally S0 forced-aligned). Event tokens carry
            the vocalization protection.
        level: legacy longform aggression 1..5. Higher -> more, shorter cuts.
            Used only when ``gap_length`` is None.
        density: legacy 0..1 fraction of the level's cuts to keep (1.0 = all).
            Used only when ``rhythm`` is None.
        gap_length: PREFERRED — the minimum pause/silence in seconds that becomes
            cuttable (``GAP_LENGTH_MIN``..``GAP_LENGTH_MAX``). Sets the silence
            floor verbatim and selects the nearest word-gap level. Lower = cut
            shorter pauses (more aggressive). When given it OVERRIDES ``level``.
        rhythm: PREFERRED — 1..5 rapid-succession dial (fractional ok; the curve
            interpolates). 5 = apply every qualifying cut; lower spaces applied
            cuts out (``_RHYTHM_SPACING``), dropping the closely-clustered short
            cuts and keeping the impactful pauses. When given it OVERRIDES
            ``density``.
        story_map: S4 StoryMap; its non-cut beats define kept material. None ->
            unconstrained (whole timeline kept).
        silences: S0 measured silences. Drive two things: (1) extra cut
            candidates from the silence grid (FIX 1), and (2) edge-snapping. None
            -> neither (cuts come only from word gaps, edges on word boundaries).
        duration: total source length, only used to bound the kept range when
            there's no StoryMap.

    Returns:
        ``[{start, end, reason}, ...]`` sorted by start, the locked contract
        shape. Every edge is a word boundary or a measured-silence edge; none
        clips a word; none falls inside a cut-intent beat.
    """
    # Resolve the aggression knobs. GAP-LENGTH / RHYTHM are the redesigned
    # controls and WIN when supplied; otherwise fall back to legacy level/density.
    #   gap_length → the silence floor verbatim + the nearest word-gap level
    #   rhythm     → a kept-content spacing the thinner enforces
    if gap_length is not None:
        # Sanitize before clamping: a non-finite gap_length → the neutral default,
        # so the clamp can't snap to an extreme on a NaN/inf (see ``_finite``).
        gap_length = max(GAP_LENGTH_MIN, min(GAP_LENGTH_MAX, _finite(gap_length, DEFAULT_GAP_LENGTH)))
        level = _level_for_gap_length(gap_length)
        silence_threshold = gap_length
    else:
        level = max(MIN_LEVEL, min(MAX_LEVEL, int(level)))
        # legacy: the silence floor scales with the chosen level
        silence_threshold = _silence_threshold_for_level(level)

    candidates = detect_edit_cuts(words, level)

    kept = kept_ranges_from_beats(story_map, duration)
    spans = _word_spans(words)
    sils = silences or []

    # FIX 1: add measured-silence candidates -- the dead-air the word-gap
    # detector is blind to. The threshold is GAP-LENGTH verbatim (the redesigned
    # knob's whole point: a continuous seconds value drives the cut floor with no
    # L2->L3 cliff); on the legacy path it scales with the level instead.
    if sils:
        candidates = candidates + silence_microcuts(
            sils, kept, spans, min_dur=silence_threshold
        )

    paced: list[EditCut] = []
    for cut in candidates:
        clipped = _clip_to_kept(cut, kept)
        if clipped is None:
            continue
        if sils:
            snapped = snap_microcut_to_silence(clipped, sils, spans)
            if snapped is None:
                continue
            # Re-clip in case a silence edge reached past the kept range.
            snapped = _clip_to_kept(snapped, kept)
            if snapped is None:
                continue
            clipped = snapped
        # Final word-safety backstop: a filler/word cut can carry an edge that
        # sits inside a *different*, overlapping forced-aligned word (alignment
        # artifact). Drop/trim such edges so the invariant holds unconditionally.
        safe = _clamp_out_of_words(clipped.start, clipped.end, spans, SILENCE_SAFETY)
        if safe is None:
            continue
        if (safe[0], safe[1]) != (clipped.start, clipped.end):
            clipped = EditCut(start=safe[0], end=safe[1], reason=clipped.reason)
        paced.append(clipped)

    # FIX 1: union overlapping candidates so a measured silence and the word-gap
    # pause beside it collapse into one cut (dedupe), rather than double-counting.
    paced.sort(key=lambda c: c.start)
    paced = _merge_overlapping(paced)

    # Consolidation: collapse rapid micro-cuts separated by a tiny near-empty
    # scrap (no content word/vocalization) into one clean cut, so an over-chopped
    # span isn't left as little bits. Word-safe — a scrap with any real word is
    # protected. Runs before density so the knob thins the consolidated set.
    paced = _consolidate_microcuts(paced, _content_spans(words))

    # Thin the qualifying cuts. RHYTHM (spacing) wins when supplied — it spaces
    # applied cuts out so rapid-fire 0.2s clusters drop while big pauses survive;
    # otherwise the legacy DENSITY (keep-fraction) thinner runs. Both only DROP
    # whole cuts, so word-safe edges are untouched.
    if rhythm is not None:
        paced = _apply_rhythm(paced, _spacing_for_rhythm(rhythm))
    else:
        # Sanitize density too: a non-finite legacy density would make
        # _apply_density's round() raise; coerce to the neutral default (keep-all).
        paced = _apply_density(paced, _finite(density, DEFAULT_DENSITY))
    paced.sort(key=lambda c: c.start)

    return [
        {"start": c.start, "end": c.end, "reason": clarify_reason(c)}
        for c in paced
    ]


# ── GLOBAL cut-transition nudge ───────────────────────────────────────────────
# Two millisecond knobs that uniformly shift every ALGORITHM cut edge AFTER the
# pacing layer (plan_microcuts → refine_onsets) has placed and word-safed it. The
# ONE shared transform both the serve path (editor_server.microcuts_payload) and
# the export path call, so what the editor previews is byte-identical to what the
# render emits (preview == export by construction).
#
# SIGN (documented, load-bearing — the editor's edge labels depend on it):
#   leadInMs  shifts each cut's TRAILING edge (``end``, the resume point). A
#             POSITIVE value pulls the resume EARLIER, leaving MORE AIR before the
#             next word (a softer, less abrupt resume):  end'  = end  - leadInMs/1000
#   tailOutMs shifts each cut's LEADING edge (``start``, the outgoing point). A
#             POSITIVE value pushes the cut start LATER, KEEPING MORE TAIL after
#             the previous word:                         start' = start + tailOutMs/1000
#
# Every shifted edge is RE-CLAMPED through ``_clamp_out_of_words`` (the shared
# word-clip backstop), so a nudge can never land an edge strictly inside a kept
# word — a clipping nudge is bounded to the word boundary. A nudge that would
# collapse a cut entirely leaves that cut at its original (already word-safe)
# edges rather than dropping it; the rule is deterministic, so both paths agree.
def apply_transition_nudge(
    cuts: list[dict[str, Any]],
    lead_in_ms: float = 0.0,
    tail_out_ms: float = 0.0,
    words: list[dict] | None = None,
) -> list[dict[str, Any]]:
    """Uniformly shift each cut's edges by the lead-in / tail-out nudge, word-safe.

    Pure: returns a NEW list and never mutates the input cuts. With BOTH knobs 0
    it is the IDENTITY — the same list object is returned untouched — so the
    default pace is byte-for-byte the pre-nudge behaviour. See the module note
    above for the sign of each knob.

    Args:
        cuts: ``[{start, end, reason}, ...]`` (the ``/api/microcuts`` shape); any
            extra keys are preserved.
        lead_in_ms: POSITIVE leaves more air before the next word (trailing edge
            earlier). Milliseconds.
        tail_out_ms: POSITIVE keeps more tail after the previous word (leading
            edge later). Milliseconds.
        words: word list used to re-clamp every shifted edge out of kept words.
            Empty/None → only the collapse guard applies (no word grid to honour).

    Returns:
        A new ``[{start, end, ...}]`` list, every edge still word-safe.
    """
    # Sanitize FIRST: a non-finite lead/tail (NaN/±inf) would otherwise shift an
    # edge to NaN/±inf and emit it as a cut boundary (a NaN survives the word-clamp
    # and serializes as invalid JSON). Coerce to 0 — the no-nudge identity — so this
    # transform is non-finite-safe by construction (see ``_finite``).
    lead = _finite(lead_in_ms, 0.0)
    tail = _finite(tail_out_ms, 0.0)
    if lead == 0.0 and tail == 0.0:
        return cuts  # identity — no nudge, nothing to shift or re-clamp
    spans = _word_spans(words or [])
    lead_s = lead / 1000.0
    tail_s = tail / 1000.0
    out: list[dict[str, Any]] = []
    for c in cuts:
        # +tail pushes the leading edge later (more tail kept); +lead pulls the
        # trailing edge earlier (more air before the next word).
        s = float(c["start"]) + tail_s
        e = float(c["end"]) - lead_s
        nc = dict(c)
        safe = _clamp_out_of_words(s, e, spans, SILENCE_SAFETY)
        if safe is not None:
            nc["start"], nc["end"] = safe[0], safe[1]
        # safe is None → the nudge collapsed the cut or no clean edge exists; keep
        # the cut's ORIGINAL (already word-safe) edges rather than drop it.
        out.append(nc)
    return out
